shell_commands:
/usr/bin/zsh -lc "cat > src/orchestration/onErrorCause.test.ts <<'EOF'
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

async function rejectWith(reason: unknown): Promise<{outcome: {rejected: boolean; reason?: unknown}; observed: Error[]}> {
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw reason;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const observed: Error[] = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test assistant'}), undefined, {
    hooks: {onError: async (_session, error) => void observed.push(error)},
  });
  const outcome = await orchestrator.processMessage(session).then(
    () => ({rejected: false}),
    (caught: unknown) => ({rejected: true, reason: caught})
  );
  return {outcome, observed};
}

it('passes an undefined rejection to onError as an Error cause (spec: specs/hal-engine-config-hooks/spec.md#9)', async () => {
  const {outcome, observed} = await rejectWith(undefined);

  expect({
    outcome,
    count: observed.length,
    isError: observed[0] instanceof Error,
    hasCause: observed[0] ? Object.hasOwn(observed[0], 'cause') : false,
    cause: observed[0]?.cause,
  }).toEqual({
    outcome: {rejected: true, reason: undefined},
    count: 1,
    isError: true,
    hasCause: true,
    cause: undefined,
  });
});

it('gives an empty string rejection a readable hook error (spec: specs/hal-engine-config-hooks/spec.md#9)', async () => {
  const {outcome, observed} = await rejectWith('');

  expect({outcome, count: observed.length, message: observed[0]?.message, cause: observed[0]?.cause}).toEqual({
    outcome: {rejected: true, reason: ''},
    count: 1,
    message: 'Unknown rejection',
    cause: '',
  });
});

it('reports an unstringifiable rejection and preserves it for the caller (spec: specs/hal-engine-config-hooks/spec.md#9)', async () => {
  const reason = Object.create(null) as object;
  const {outcome, observed} = await rejectWith(reason);

  expect({
    outcome,
    count: observed.length,
    isError: observed[0] instanceof Error,
    message: observed[0]?.message,
    cause: observed[0]?.cause,
  }).toEqual({
    outcome: {rejected: true, reason},
    count: 1,
    isError: true,
    message: 'Unknown rejection',
    cause: reason,
  });
});
EOF"
